from parcel_seed s cross join public.jurisdictions j where j.slug = 'clearwater-fl'
on conflict (jurisdiction_id, parcel_identifier) do update set
  source_parcel_identifier=excluded.source_parcel_identifier, zoning_code=excluded.zoning_code, zoning_description=excluded.zoning_description,
