insert into public.property_addresses (property_id, jurisdiction_id, display_address, normalized_address, source_address_identifier, match_method, active)
select p.id, p.jurisdiction_id, s.display_address, s.normalized_address, s.source_address_identifier, s.match_method, true
from address_seed s join public.jurisdictions j on j.slug='clearwater-fl'
join public.properties p on p.jurisdiction_id=j.id and p.parcel_identifier=s.parcel_identifier and p.validation_status='clean'
on conflict (property_id, source_address_identifier) do update set display_address=excluded.display_address, normalized_address=excluded.normalized_address, match_method=excluded.match_method, active=true;
